import{_ as t,c as r,o,a5 as i}from"./chunks/framework.DuCYAsAJ.js";const f=JSON.parse('{"title":"互动与搜索 API 处理器","description":"","frontmatter":{"title":"互动与搜索 API 处理器","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#2.4","branch":"main","level":1,"order":2.4},"headers":[],"relativePath":"posts/projects/zfeed/02-front-api-gateway/04-interaction-and-search-api-handlers.md","filePath":"posts/projects/zfeed/02-front-api-gateway/04-interaction-and-search-api-handlers.md","lastUpdated":1779632679000}'),a={name:"posts/projects/zfeed/02-front-api-gateway/04-interaction-and-search-api-handlers.md"};function c(n,e,l,p,g,b){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="互动与搜索-api-处理器" tabindex="-1">互动与搜索 API 处理器 <a class="header-anchor" href="#互动与搜索-api-处理器" aria-label="Permalink to &quot;互动与搜索 API 处理器&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/interaction/interaction.api" target="_blank" rel="noreferrer">app/front/doc/interaction/interaction.api</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/batchquerylikeinfologic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/batchquerylikeinfologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/commentlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/commentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/deletecommentlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/deletecommentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/favoritelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/favoritelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/followuserlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/followuserlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/likelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/likelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/querycommentlistlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/querycommentlistlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/queryfavoriteinfologic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/queryfavoriteinfologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/queryreplycommentlistlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/queryreplycommentlistlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/removefavoritelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/removefavoritelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/scene.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/scene.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/unfollowuserlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/unfollowuserlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/unlikelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/unlikelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchcontentslogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchcontentslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchlogic_test.go" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchlogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchuserslogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchuserslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/favorite_strategy.go" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/favorite_strategy.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/client/commentservice/commentservice.go" target="_blank" rel="noreferrer">app/rpc/interaction/client/commentservice/commentservice.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/client/favoriteservice/favoriteservice.go" target="_blank" rel="noreferrer">app/rpc/interaction/client/favoriteservice/favoriteservice.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/client/followservice/followservice.go" target="_blank" rel="noreferrer">app/rpc/interaction/client/followservice/followservice.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/client/likeservice/likeservice.go" target="_blank" rel="noreferrer">app/rpc/interaction/client/likeservice/likeservice.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/interaction/interaction_grpc.pb.go" target="_blank" rel="noreferrer">app/rpc/interaction/interaction/interaction_grpc.pb.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/do/favorite_do.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/do/favorite_do.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/batchgetcommentslogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/batchgetcommentslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/deletecommentlogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/deletecommentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/querycommentlistlogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/querycommentlistlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/queryreplylistlogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/queryreplylistlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/refillcommentcachelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/refillcommentcachelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/model/interaction_model.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/model/interaction_model.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/favorite_repository.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/favorite_repository.go</a></li></ul></details><p>本文说明 <code>front-api</code> 网关中社交互动和搜索处理器的实现。这些处理器作为路由与校验层，通过协调 <code>interaction-rpc</code> 和 <code>search-rpc</code> 服务，把复杂领域逻辑封装成简单的 HTTP 端点。</p><h2 id="互动-api-处理器" tabindex="-1">互动 API 处理器 <a class="header-anchor" href="#互动-api-处理器" aria-label="Permalink to &quot;互动 API 处理器&quot;">​</a></h2><p>互动子系统覆盖点赞、收藏、关注和楼中楼评论。大多数互动端点都要求通过 <code>UserLoginStatusAuthMiddleware</code> 完成认证。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/interaction/interaction.api#L169-L169" target="_blank" rel="noreferrer">app/front/doc/interaction/interaction.api#169</a></p><h3 id="scene-抽象" tabindex="-1">Scene 抽象 <a class="header-anchor" href="#scene-抽象" aria-label="Permalink to &quot;Scene 抽象&quot;">​</a></h3><p>互动请求使用 <code>Scene</code> 参数（例如 <code>&quot;content&quot;</code>、<code>&quot;comment&quot;</code>）将动作路由到正确的领域上下文。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/interaction/interaction.api#L9-L9" target="_blank" rel="noreferrer">app/front/doc/interaction/interaction.api#9</a> <code>front-api</code> 会先把这些字符串解析为内部枚举值，再传给 RPC 服务。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/likelogic.go#L42-L45" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/likelogic.go#42-45</a></p><h3 id="实现模式-点赞与收藏" tabindex="-1">实现模式：点赞与收藏 <a class="header-anchor" href="#实现模式-点赞与收藏" aria-label="Permalink to &quot;实现模式：点赞与收藏&quot;">​</a></h3><p>点赞和收藏操作遵循统一模式：</p><ol><li>身份提取：从请求上下文获取 <code>userID</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/likelogic.go#L37-L40" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/likelogic.go#37-40</a></li><li>Scene 校验：将字符串 scene 转换为类型化的 RPC scene。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/likelogic.go#L42-L45" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/likelogic.go#42-45</a></li><li>RPC 委托：调用对应的 <code>LikeRpc</code> 或 <code>FavoriteRpc</code> 方法。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/likelogic.go#L47-L51" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/likelogic.go#47-51</a></li></ol><h3 id="楼中楼评论系统" tabindex="-1">楼中楼评论系统 <a class="header-anchor" href="#楼中楼评论系统" aria-label="Permalink to &quot;楼中楼评论系统&quot;">​</a></h3><p>评论系统支持嵌套回复（parent/root 层级）。<code>front-api</code> 通过同一个 <code>Comment</code> handler 同时处理根评论创建和回复创建。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/interaction/interaction.api#L199-L200" target="_blank" rel="noreferrer">app/front/doc/interaction/interaction.api#199-200</a></p><p>数据流：创建评论</p><ol><li>校验：<code>front-api</code> 校验内容长度（最多 255 个 rune）和必填 ID。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/interaction/interaction.api#L60-L65" target="_blank" rel="noreferrer">app/front/doc/interaction/interaction.api#60-65</a></li><li>楼层解析：<code>interaction-rpc</code> 服务解析 <code>parent_id</code> 和 <code>root_id</code>，确保评论层级有效。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L154-L196" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#154-196</a></li><li>事务写入：评论被创建，同时根评论的回复数会在同一个 MySQL 事务中递增。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L66-L98" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#66-98</a></li><li>缓存失效：创建后，系统会让相关 Redis key 失效，包括内容评论列表和特定评论串。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L112-L152" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#112-152</a></li></ol><p>评论缓存架构采用两层 Redis 缓存策略：</p><ul><li>索引缓存：使用 <code>ZSet</code> 存储评论 ID，并按 score 排序（通常是时间戳或 ID）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go#L23-L48" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go#23-48</a></li><li>对象缓存：将单条评论详情以 JSON 字符串形式存储，并设置特定 TTL。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go#L93-L114" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go#93-114</a></li></ul><h3 id="互动请求路由" tabindex="-1">互动请求路由 <a class="header-anchor" href="#互动请求路由" aria-label="Permalink to &quot;互动请求路由&quot;">​</a></h3><p>下图展示 <code>front-api</code> 如何将 HTTP 请求路由到具体的 RPC 服务逻辑。</p><p>互动路由图</p><table tabindex="0"><thead><tr><th>实体</th><th>说明</th><th>文件路径</th></tr></thead><tbody><tr><td><code>LikeReq</code></td><td>点赞内容的输入结构</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/interaction/interaction.api#L6-L10" target="_blank" rel="noreferrer">app/front/doc/interaction/interaction.api#6-10</a></td></tr><tr><td><code>CommentItem</code></td><td>标准化评论数据结构</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/interaction/interaction.api#L80-L93" target="_blank" rel="noreferrer">app/front/doc/interaction/interaction.api#80-93</a></td></tr><tr><td><code>CommentLogic</code></td><td>评论操作的 RPC 逻辑</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L21-L37" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#21-37</a></td></tr><tr><td><code>BatchGetComments</code></td><td>多条评论的优化读取入口</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/batchgetcommentslogic.go#L30-L73" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/batchgetcommentslogic.go#30-73</a></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/interaction/interaction.api#L1-L220" target="_blank" rel="noreferrer">app/front/doc/interaction/interaction.api#1-220</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/likelogic.go#L1-L56" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/likelogic.go#1-56</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L1-L110" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#1-110</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go#L1-L114" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go#1-114</a></p><hr><h2 id="搜索-api-处理器" tabindex="-1">搜索 API 处理器 <a class="header-anchor" href="#搜索-api-处理器" aria-label="Permalink to &quot;搜索 API 处理器&quot;">​</a></h2><p>搜索处理器为用户发现和内容发现提供统一入口。它们会把 HTTP 查询参数转换为 <code>search-rpc</code> 请求，并支持多种排序模式，以及通过快照实现的稳定分页。</p><h3 id="搜索请求处理" tabindex="-1">搜索请求处理 <a class="header-anchor" href="#搜索请求处理" aria-label="Permalink to &quot;搜索请求处理&quot;">​</a></h3><p><code>front-api</code> 会执行基础清洗，例如裁剪空白字符，并限制最大分页大小（默认 20）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchuserslogic.go#L16-L48" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchuserslogic.go#16-48</a></p><p>关键能力：</p><ul><li>搜索模式：支持 <code>relevance</code>、<code>latest</code> 或 <code>hybrid</code> 排序。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchlogic_test.go#L79-L80" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchlogic_test.go#79-80</a></li><li>查看者上下文：如果用户已登录，会将其 <code>viewerID</code> 传给 RPC，用于补全结果状态（例如 <code>IsFollowing</code>）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchuserslogic.go#L55-L75" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchuserslogic.go#55-75</a></li><li>稳定分页：使用 <code>SnapshotId</code> 和 <code>PageToken</code>，确保底层索引变化时，用户不会看到重复结果或跳过结果。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchcontentslogic.go#L62-L70" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchcontentslogic.go#62-70</a></li></ul><h3 id="搜索数据流" tabindex="-1">搜索数据流 <a class="header-anchor" href="#搜索数据流" aria-label="Permalink to &quot;搜索数据流&quot;">​</a></h3><p>搜索流程连接了 <code>front-api</code> 类型和 <code>search-rpc</code> protobuf 定义。</p><p>搜索补全图</p><h3 id="内容搜索与用户搜索" tabindex="-1">内容搜索与用户搜索 <a class="header-anchor" href="#内容搜索与用户搜索" aria-label="Permalink to &quot;内容搜索与用户搜索&quot;">​</a></h3><ul><li>内容搜索：返回包括 <code>AuthorName</code>、<code>CoverUrl</code> 和 <code>PublishedAt</code> 在内的元数据。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchcontentslogic.go#L85-L94" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchcontentslogic.go#85-94</a></li><li>用户搜索：包含 <code>IsFollowing</code> 布尔值，该值由 <code>search-rpc</code> 根据 <code>viewerID</code> 和搜索结果之间的关系检查后补全。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchuserslogic.go#L87-L93" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchuserslogic.go#87-93</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchcontentslogic.go#L1-L104" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchcontentslogic.go#1-104</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchuserslogic.go#L1-L104" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchuserslogic.go#1-104</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/search/searchlogic_test.go#L1-L134" target="_blank" rel="noreferrer">app/front/internal/logic/search/searchlogic_test.go#1-134</a></p>',34)])])}const d=t(a,[["render",c]]);export{f as __pageData,d as default};
